import com.holdmyspot.codexunleashed.scheduler.LinuxProcessTree;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

/** Exercises natural completion and premature close through the public Java owner. */
public final class NaturalCompletionGate {
    private static Path classes;
    private static Path fixture;
    private static Path python;
    private static Path parent;
    private static int uid;
    private static int gid;

    /** Uses explicit platform inputs in a standalone privileged supervisor JVM. */
    public static void main(String[] args) throws Exception {
        classes = Path.of(args[0]);
        System.out.println("owner_module=" + LinuxProcessTree.class.getModule().getName());
        System.out.println("owner_module=" + LinuxProcessTree.class.getModule().getName());
        Path work = Path.of(args[1]);
        fixture = Path.of(args[2]);
        python = Path.of(args[3]);
        uid = Integer.parseInt(args[4]);
        gid = Integer.parseInt(args[5]);
        parent = Path.of(args[6]);
        Files.createDirectory(work);
        Files.setPosixFilePermissions(work, PosixFilePermissions.fromString("rwxrwxrwx"));
        Files.writeString(parent.resolve("cgroup.procs"), Long.toString(ProcessHandle.current().pid()));
        System.out.println("owner_origin=" + LinuxProcessTree.class.getProtectionDomain().getCodeSource().getLocation());
        natural(work.resolve("root0"), 0, 0);
        Files.delete(work);
        System.out.println("natural_gate=passed");
    }

    /** Creates the same trusted gated launch as the accepted termination driver. */
    private static LinuxProcessTree.Launch launch(Path work, int rootExit, int leafExit) throws Exception {
        Files.createDirectory(work);
        Files.setPosixFilePermissions(work, PosixFilePermissions.fromString("rwxrwxrwx"));
        return new LinuxProcessTree.Launch(parent, work,
            Path.of(System.getProperty("java.home"), "bin", "java"), classes,
            List.of(python.toString(), fixture.toString(), "natural-root", work.resolve("root.properties").toString(),
                work.resolve("leaf.properties").toString(), work.resolve("leaf.release").toString(),
                Integer.toString(rootExit), Integer.toString(leafExit)),
            Map.of("OWNER_GATE_TOKEN", "java-owner-exact-environment"), work, uid, gid);
    }

    /** Holds the descendant until after pending observation, then collects its actual natural status. */
    private static void natural(Path work, int rootExit, int leafExit) throws Exception {
        Path group;
        Path scratch;
        LinuxProcessTree tree = LinuxProcessTree.prepare(launch(work, rootExit, leafExit));
        try (tree) {
            group = tree.group();
            scratch = tree.scratch();
            check(Files.exists(work.resolve("root.properties")) == false, "Workload executed before release");
            check(tree.members().contains(tree.rootPid()), "Trusted gate lacked containment");
            tree.release();
            check(tree.awaitRootExit() == rootExit, "Natural root status differed");
            Properties leaf = readEventually(work.resolve("leaf.properties"));
            long leafPid = Long.parseLong(leaf.getProperty("pid"));
            check(Long.parseLong(leaf.getProperty("pgid")) == leafPid, "Natural child did not detach");
            check(tree.members().contains(leafPid), "Natural child escaped containment");
            check(tree.isComplete() == false, "Root exit completed a held tree");
            check(tree.observeCompletion() == false, "Held descendant was reported complete");
            check(tree.terminationRequested() == false, "Pending observation requested termination");
            Files.writeString(work.resolve("leaf.release"), "release\n");
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (tree.observeCompletion() == false) {
                if (System.nanoTime() >= deadline)
                    throw new AssertionError("Natural completion remained pending after descendant release");
                Thread.sleep(10);
            }
            check(tree.isComplete(), "Natural completion was not retained");
            check(tree.observeCompletion(), "Repeated completion observation regressed");
            check(tree.awaitRootExit() == rootExit, "Natural reaping changed root status");
            check(Integer.valueOf(leafExit).equals(tree.adoptedExits().get(leafPid)),
                "Missing actual natural child status: " + tree.adoptedExits());
            check(tree.terminationRequested() == false, "Natural reaping requested termination");
            System.out.println("root" + rootExit + "_adopted_exit=" + tree.adoptedExits().get(leafPid));
        }
        check(tree.terminationRequested() == false, "Natural close requested termination");
        check(Files.exists(group) == false && Files.exists(scratch) == false, "Natural close retained owned storage");
        clear(work);
        System.out.println("root" + rootExit + "_natural_cleanup=passed");
    }

    /** Closing before descendant completion must remain a termination outcome even for root0. */
    private static void premature(Path work) throws Exception {
        LinuxProcessTree tree = LinuxProcessTree.prepare(launch(work, 0, 0));
        Path group = tree.group();
        Path scratch = tree.scratch();
        long leafPid;
        try (tree) {
            tree.release();
            check(tree.awaitRootExit() == 0, "Premature-close root did not return0");
            leafPid = Long.parseLong(readEventually(work.resolve("leaf.properties")).getProperty("pid"));
            check(tree.observeCompletion() == false, "Held premature-close child completed");
        }
        check(tree.terminationRequested(), "Premature close lost termination outcome after root0");
        check(Integer.valueOf(-9).equals(tree.adoptedExits().get(leafPid)), "Premature close lacks SIGKILL wait status");
        check(Files.exists(group) == false && Files.exists(scratch) == false, "Premature close retained owned storage");
        clear(work);
        System.out.println("premature_close=passed");
    }

    /** Reads atomically published fixture data with an independent bounded wait. */
    private static Properties readEventually(Path path) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (Files.exists(path) == false) {
            if (System.nanoTime() >= deadline) throw new AssertionError("Missing fixture report: " + path);
            Thread.sleep(10);
        }
        Properties result = new Properties();
        try (InputStream input = Files.newInputStream(path)) { result.load(input); }
        return result;
    }

    /** Removes only the completed fixture's own ordinary files. */
    private static void clear(Path path) throws Exception {
        try (var entries = Files.list(path)) {
            for (Path entry : entries.toList()) Files.delete(entry);
        }
        Files.delete(path);
    }

    /** Makes each required observable behavior an assertion. */
    private static void check(boolean value, String message) {
        if (value == false) throw new AssertionError(message);
    }
}
